INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (100, 292, 'color POF Film included POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form', '../upload/image/20180925/20180925213229_39031.jpg', '<p></p><p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Color POF shrinkage cling film (POF film,Polyolefin Shrink Film)</span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;"><strong>Types: color POF Film included POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form </strong></span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">FOF film have center fold or single.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">POF Thermal Shrinkable Cling Film (Polyolefin Shrink Film - Center Folded),</span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Types:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">1. POF cling film (Polyolefin Shrink Film - Center Folded or Tubular form,</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Normal size: 19mic x 45cm x 1000Mtr</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Thickness of POF Thermal Shrinkable Cling Film :12-25 microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Width of POF Thermal Shrinkable Cling Film: 100-1500MM</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Length of POF Film: 500-3000M Inner core: 3",6",1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">POF shrinkage film, POF FILM,Polyolefin Shrink Film,Shrink Film,POF macro perforated cling film</span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <br/></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;"><strong>2. <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;"><strong>POF Tubular Form cling film ( POF film- Tubular Form )</strong></span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Thickness of POF POF Tubular Form heat shrink cling film:15,25,30. microns</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Width of POF heat shrink cling film: 100-1500MM</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Length of POF heat shrink cling film: 500-1500M</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Inner core of POF film in rolls: 3", 6",1.8"</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;font-style:normal;">Packing of POF film rolls: inner package in carton and outer packing in pallets</span></strong></span></p> <p style=''text-align:left;color:#878D95;text-indent:0px;font-family:"font-size:14px;font-style:normal;font-weight:normal;''> <br/></p>', '2026-09-06 20:58:45');